theme.css:
/* theme: Dust and Leverage | Spain's grief collides with Israel's political stalemate — a page of dusty ochre, dense urgency, and the brittle calculus of power. */
/* layout: hero=centered; political-news=outline/stack; financial-news=stat/grid-2; entertainment-news=tile/grid-2; sports=timeline/stack; music-releases=numbered/masonry; stock-analysis=stat/grid-3; outlook=lede/stack */

.diary-page {
  --paper: #f4efe6;
  --paper-alt: #e9e0d0;
  --ink: #2b2318;
  --ink-soft: #4a3f30;
  --muted: #6b5c48;
  --accent: #a63c1e;
  --accent-ink: #fdfaf5;
  --rule: #d4c49f;
  --font-display: var(--ff-playfair), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), sans-serif;
}

.diary-page {
  background: var(--paper);
  color: var(--ink-soft);
  font-family: var(--font-body);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--ink);
  position: relative;
}

.diary-page .diary-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 6px;
  background: repeating-linear-gradient(90deg, var(--accent) 0 12px, transparent 12px 24px);
}

.diary-page .diary-hero-inner {
  padding-top: 2.5rem;
  max-width: 48rem;
}

.diary-page .diary-kicker {
  margin-top: 1.5rem;
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-title {
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  font-style: italic;
  text-transform: uppercase;
}

.diary-page .diary-summary {
  margin-top: 1.75rem;
  font-size: clamp(1.15rem, 2vw, 1.4rem);
  line-height: 1.7;
  color: var(--ink);
  font-weight: 500;
  max-width: 40rem;
}

.diary-page .diary-theme-note {
  margin-top: 1.5rem;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
  border-top: 1px solid var(--rule);
  padding-top: 1rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.diary-page .diary-toc {
  background: var(--paper);
  box-shadow: 0 2px 0 var(--rule);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section {
  border-top: 0;
  padding-block: 2.5rem;
}

.diary-page .diary-section + .diary-section {
  margin-top: 2rem;
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  margin-bottom: 1.5rem;
  gap: 1rem;
  align-items: center;
}

.diary-page .diary-section-number {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.14em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  font-size: clamp(1.8rem, 3.5vw, 2.75rem);
}

.diary-page .diary-card {
  container-type: inline-size;
}

.diary-page .diary-prose {
  font-size: 1.15rem;
  line-height: 1.75;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
  text-decoration: none;
  font-weight: 600;
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  color: var(--ink);
  font-style: italic;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

/* Political news: heavy editorial outline, dense column */
.diary-page [data-section="political-news"] .diary-card--outline .diary-card-inner {
  padding: 2rem;
  border: 2px solid var(--ink);
  background: var(--paper);
  box-shadow: 6px 6px 0 rgba(43, 35, 24, 0.12);
}

.diary-page [data-section="political-news"] .diary-card--outline .diary-card-title {
  font-size: 2.2rem;
  font-style: italic;
  margin-bottom: 0.25rem;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  color: var(--ink);
}

.diary-page [data-section="political-news"] .diary-prose {
  font-size: 1.3rem;
  line-height: 1.7;
  max-width: 68ch;
}

.diary-page [data-section="political-news"] .diary-card-body > p:first-of-type::first-letter {
  float: left;
  margin: 0.06em 0.1em 0 0;
  font-family: var(--font-display);
  font-size: 3.6em;
  font-weight: 700;
  line-height: 0.8;
  color: var(--accent);
}

/* Financial: stat cards with a ledger feel */
.diary-page [data-section="financial-news"] .diary-card--stat {
  border-top: 4px solid var(--ink);
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  padding-top: 0.25rem;
  border-top: 0;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-size: clamp(2rem, 10cqi, 3.4rem);
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page [data-section="financial-news"] .diary-card-title {
  font-size: 1.4rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink);
}

/* Entertainment: warm, soft tiles like a film strip */
.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  position: relative;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner::after {
  content: "✦";
  position: absolute;
  top: 0.75rem;
  right: 1rem;
  font-size: 1rem;
  color: var(--accent);
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-style: italic;
  font-size: 1.7rem;
  color: var(--ink);
}

/* Sports: timeline rail with dots — a game log */
.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner {
  padding-left: 2.25rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::before {
  left: 0.45rem;
  top: 0;
  bottom: -1.5rem;
  width: 3px;
  background: var(--rule);
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::after {
  left: 0;
  top: 0.45rem;
  width: 1rem;
  height: 1rem;
  border-radius: 0;
  transform: rotate(45deg);
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page [data-section="sports"] .diary-card-title {
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ink);
}

/* Music: numbered cards, airy */
.diary-page [data-section="music-releases"] .diary-card--numbered .diary-card-index {
  color: var(--accent);
  font-size: 2.5rem;
  font-weight: 700;
  font-style: italic;
}

.diary-page [data-section="music-releases"] .diary-card--numbered .diary-card-inner {
  column-gap: 1rem;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.5rem;
  color: var(--ink);
}

.diary-page [data-section="music-releases"] .diary-embed {
  border-radius: 8px;
  border: 1px solid var(--rule);
}

/* Stock: tight stats, market tape vibe */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  background: var(--paper-alt);
  padding: 0.75rem 0.75rem 0.5rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-size: clamp(1.8rem, 8cqi, 2.75rem);
  letter-spacing: -0.03em;
  color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.9rem;
  line-height: 1.6;
}

.diary-page [data-section="stock-analysis"] .diary-prose a {
  font-size: 0.65em;
}

/* Outlook: lede cards that read as items on a clipboard */
.diary-page [data-section="outlook"] .diary-card--lede .diary-card-lede {
  margin-left: 0;
  margin-right: 0;
  padding: 0.75rem 1.25rem;
  background: var(--paper-alt);
  border-left: 4px solid var(--accent);
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.15rem;
  color: var(--ink);
}

.diary-page [data-section="outlook"] .diary-card--lede .diary-card-title {
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink);
}

.diary-page [data-section="outlook"] .diary-card--lede .diary-card-body {
  margin-top: 0.5rem;
}

/* Merged card title adjustments */
.diary-page .diary-card-title {
  font-weight: 700;
  line-height: 1.15;
}

.diary-page .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.68;
}

@container article (min-width: 40rem) {
  .diary-page [data-section="sports"] .diary-stories--grid-2 {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 1024px) {
  .diary-page .diary-hero-inner {
    padding-top: 3rem;
  }

  .diary-page .diary-hero::after {
    height: 8px;
  }

  .diary-page [data-section="political-news"] .diary-card--outline .diary-card-inner {
    padding: 2.5rem;
  }
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #1b1712;
    --paper-alt: #241e16;
    --ink: #f3ead9;
    --ink-soft: #cfc2ac;
    --muted: #9e8d6e;
    --accent: #e0703e;
    --accent-ink: #1b120b;
    --rule: #40382c;
  }

  .diary-page .diary-hero::after {
    background: repeating-linear-gradient(90deg, var(--accent) 0 12px, transparent 12px 24px);
  }

  .diary-page [data-section="political-news"] .diary-card--outline .diary-card-inner {
    border-color: var(--ink);
    box-shadow: 6px 6px 0 rgba(0, 0, 0, 0.3);
  }

  .diary-page [data-section="financial-news"] .diary-card--stat {
    border-top-color: var(--ink);
  }

  .diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner::after {
    color: var(--accent);
  }

  .diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::after {
    box-shadow: 0 0 0 4px var(--paper);
  }

  .diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
    background: var(--paper-alt);
  }

  .diary-page [data-section="outlook"] .diary-card--lede .diary-card-lede {
    background: var(--paper-alt);
  }
}
